    "id": "Q74",
    "number": "Question 74",
    "unitId": "unit-4",
    "unitTitle": "Unit 4: Loss Functions & Categorical/Cross-Entropy Numericals",
    "title": "Definition and Fundamental Role of Loss Functions",
    "type": "Theory & Concept",
