    "id": "Q138",
    "number": "Question 138",
    "unitId": "unit-8",
    "unitTitle": "Unit 8: Regularization, Dropout & Regularization Numericals",
    "title": "Definition and Fundamental Purpose of Regularization",
    "type": "Theory & Concept",
