    "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 740 320\" width=\"100%\" height=\"100%\" class=\"diagram-svg\">\n      \n    <defs>\n      <linearGradient id=\"bgGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n        <stop offset=\"0%\" stop-color=\"#0f172a\"/>\n        <stop offset=\"100%\" stop-color=\"#1e1e38\"/>\n      </linearGradient>\n      <linearGradient id=\"primaryGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n        <stop offset=\"0%\" stop-color=\"#6366f1\"/>\n        <stop offset=\"100%\" stop-color=\"#8b5cf6\"/>\n      </linearGradient>\n      <linearGradient id=\"cyanGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n        <stop offset=\"0%\" stop-color=\"#06b6d4\"/>\n        <stop offset=\"100%\" stop-color=\"#3b82f6\"/>\n      </linearGradient>\n      <linearGradient id=\"emeraldGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n        <stop offset=\"0%\" stop-color=\"#10b981\"/>\n        <stop offset=\"100%\" stop-color=\"#059669\"/>\n      </linearGradient>\n      <linearGradient id=\"amberGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n        <stop offset=\"0%\" stop-color=\"#f59e0b\"/>\n        <stop offset=\"100%\" stop-color=\"#d97706\"/>\n      </linearGradient>\n      <linearGradient id=\"roseGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n        <stop offset=\"0%\" stop-color=\"#f43f5e\"/>\n        <stop offset=\"100%\" stop-color=\"#e11d48\"/>\n      </linearGradient>\n      <filter id=\"glow\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n        <feGaussianBlur stdDeviation=\"4\" result=\"blur\" />\n        <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\" />\n      </filter>\n      <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n        <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#94a3b8\" />\n      </marker>\n      <marker id=\"arrow-cyan\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n        <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#38bdf8\" />\n      </marker>\n      <marker id=\"arrow-emerald\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n        <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#34d399\" />\n      </marker>\n      <marker id=\"arrow-rose\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n        <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#fb7185\" />\n      </marker>\n    </defs>\n    \n      <rect width=\"740\" height=\"320\" rx=\"16\" fill=\"url(#bgGrad)\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n      \n        <rect x=\"20\" y=\"16\" width=\"700\" height=\"34\" rx=\"8\" fill=\"#1e293b\" fill-opacity=\"0.8\" stroke=\"#334155\" stroke-width=\"1\"/>\n        <circle cx=\"36\" cy=\"33\" r=\"5\" fill=\"#6366f1\"/>\n        <text x=\"50\" y=\"38\" fill=\"#f8fafc\" font-size=\"14\" font-family=\"system-ui, -apple-system, sans-serif\" font-weight=\"600\">Comprehensive Problem 3: Two-Layer Complete Backpropagation Gradient Calculation</text>\n        \n      \n    <g transform=\"translate(40, 60)\">\n      <rect width=\"200\" height=\"42\" rx=\"6\" fill=\"#0f172a\" stroke=\"#334155\"/>\n      <line x1=\"15\" y1=\"18\" x2=\"45\" y2=\"18\" stroke=\"#38bdf8\" stroke-width=\"2.5\" marker-end=\"url(#arrow-cyan)\"/>\n      <text x=\"55\" y=\"22\" fill=\"#38bdf8\" font-size=\"11\" font-weight=\"600\">Forward Pass (Values)</text>\n      <line x1=\"15\" y1=\"32\" x2=\"45\" y2=\"32\" stroke=\"#fb7185\" stroke-width=\"2\" stroke-dasharray=\"3,2\" marker-end=\"url(#arrow-rose)\"/>\n      <text x=\"55\" y=\"36\" fill=\"#fb7185\" font-size=\"11\" font-weight=\"600\">Backward Pass (Gradients)</text>\n    </g>\n    \n    <circle cx=\"80\" cy=\"140\" r=\"22\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n    <text x=\"80\" y=\"144\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"12\" font-weight=\"700\">x</text>\n    \n    <circle cx=\"80\" cy=\"220\" r=\"22\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n    <text x=\"80\" y=\"224\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"12\" font-weight=\"700\">w</text>\n    \n    <line x1=\"102\" y1=\"140\" x2=\"200\" y2=\"175\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arrow-cyan)\"/>\n    <line x1=\"102\" y1=\"220\" x2=\"200\" y2=\"185\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arrow-cyan)\"/>\n    \n    <circle cx=\"220\" cy=\"180\" r=\"26\" fill=\"url(#cyanGrad)\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n    <text x=\"220\" y=\"185\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"14\" font-weight=\"700\">*</text>\n    <text x=\"220\" y=\"222\" text-anchor=\"middle\" fill=\"#7dd3fc\" font-size=\"11\">u = x·w</text>\n    \n    <circle cx=\"220\" cy=\"100\" r=\"20\" fill=\"#1e293b\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n    <text x=\"220\" y=\"104\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"700\">b</text>\n    \n    <line x1=\"246\" y1=\"180\" x2=\"350\" y2=\"160\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arrow-cyan)\"/>\n    <line x1=\"240\" y1=\"105\" x2=\"350\" y2=\"150\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arrow-cyan)\"/>\n    \n    <circle cx=\"370\" cy=\"160\" r=\"26\" fill=\"url(#primaryGrad)\" stroke=\"#a5b4fc\" stroke-width=\"2\"/>\n    <text x=\"370\" y=\"166\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"16\" font-weight=\"700\">+</text>\n    <text x=\"370\" y=\"202\" text-anchor=\"middle\" fill=\"#a5b4fc\" font-size=\"11\">z = u+b</text>\n    \n    <line x1=\"396\" y1=\"160\" x2=\"490\" y2=\"160\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arrow-cyan)\"/>\n    <circle cx=\"515\" cy=\"160\" r=\"26\" fill=\"url(#emeraldGrad)\" stroke=\"#6ee7b7\" stroke-width=\"2\"/>\n    <text x=\"515\" y=\"165\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"13\" font-weight=\"700\">σ/f</text>\n    <text x=\"515\" y=\"202\" text-anchor=\"middle\" fill=\"#6ee7b7\" font-size=\"11\">a = f(z)</text>\n    \n    <line x1=\"541\" y1=\"160\" x2=\"630\" y2=\"160\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arrow-cyan)\"/>\n    <circle cx=\"655\" cy=\"160\" r=\"26\" fill=\"url(#roseGrad)\" stroke=\"#fca5a5\" stroke-width=\"2\"/>\n    <text x=\"655\" y=\"165\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"14\" font-weight=\"700\">Loss</text>\n    <text x=\"655\" y=\"202\" text-anchor=\"middle\" fill=\"#fca5a5\" font-size=\"11\">L(a, y)</text>\n    \n    <path d=\"M 630 145 C 570 125, 430 125, 396 145\" fill=\"none\" stroke=\"#fb7185\" stroke-width=\"2\" stroke-dasharray=\"4,3\" marker-end=\"url(#arrow-rose)\"/>\n    <text x=\"515\" y=\"120\" text-anchor=\"middle\" fill=\"#fb7185\" font-size=\"11\" font-weight=\"600\">∂L/∂a = (a-y)</text>\n    \n    <path d=\"M 490 145 C 450 130, 400 130, 370 130\" fill=\"none\" stroke=\"#fb7185\" stroke-width=\"2\" stroke-dasharray=\"4,3\"/>\n    <text x=\"370\" y=\"85\" text-anchor=\"middle\" fill=\"#fb7185\" font-size=\"11\" font-weight=\"600\">∂L/∂z = (∂L/∂a)·f'(z)</text>\n    \n    <path d=\"M 345 175 C 280 200, 180 215, 105 220\" fill=\"none\" stroke=\"#fb7185\" stroke-width=\"2\" stroke-dasharray=\"4,3\" marker-end=\"url(#arrow-rose)\"/>\n    <text x=\"175\" y=\"270\" text-anchor=\"middle\" fill=\"#fb7185\" font-size=\"11\" font-weight=\"600\">∂L/∂w = (∂L/∂z) · x</text>\n    \n    </svg>",
